"use strict";(self.webpackChunktcc_docs=self.webpackChunktcc_docs||[]).push([["6243"],{6561(r,e,n){n.r(e),n.d(e,{metadata:()=>t,default:()=>p,frontMatter:()=>i,contentTitle:()=>o,toc:()=>l,assets:()=>d});var t=JSON.parse('{"id":"Perl/scripts/create_www_professores","title":"create_www_professores","description":"Apresenta listagem de professores.","source":"@site/docs/Perl/scripts/create_www_professores.mdx","sourceDirName":"Perl/scripts","slug":"/Perl/scripts/create_www_professores","permalink":"/tcc-docs/docs/Perl/scripts/create_www_professores","draft":false,"unlisted":false,"editUrl":"https://github.com/ruseleredu/tcc-docs/edit/main/docs/Perl/scripts/create_www_professores.mdx","tags":[],"version":"current","lastUpdatedBy":"Adriano Ruseler","lastUpdatedAt":1789150874000,"sidebarPosition":55,"frontMatter":{"id":"create_www_professores","title":"create_www_professores","sidebar_position":55,"description":"Apresenta listagem de professores."},"sidebar":"tutorialSidebar","previous":{"title":"create_www_orientadores_equipes","permalink":"/tcc-docs/docs/Perl/scripts/create_www_orientadores_equipes"},"next":{"title":"create_www_professores_basic","permalink":"/tcc-docs/docs/Perl/scripts/create_www_professores_basic"}}'),a=n(74848),s=n(28453);let i={id:"create_www_professores",title:"create_www_professores",sidebar_position:55,description:"Apresenta listagem de professores."},o="create_www_professores.pl",d={},l=[{value:"Overview",id:"overview",level:2},{value:"Perl Modules",id:"perl-modules",level:2},{value:"Database",id:"database",level:2},{value:"Command-Line Options",id:"command-line-options",level:2},{value:"Example",id:"example",level:3},{value:"Source Code",id:"source-code",level:2}];function c(r){let e={code:"code",h1:"h1",h2:"h2",h3:"h3",header:"header",li:"li",p:"p",pre:"pre",strong:"strong",table:"table",tbody:"tbody",td:"td",th:"th",thead:"thead",tr:"tr",ul:"ul",...(0,s.R)(),...r.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(e.header,{children:(0,a.jsx)(e.h1,{id:"create_www_professorespl",children:(0,a.jsx)(e.code,{children:"create_www_professores.pl"})})}),"\n",(0,a.jsx)(e.p,{children:"Apresenta listagem de professores."}),"\n",(0,a.jsx)(e.h2,{id:"overview",children:"Overview"}),"\n",(0,a.jsx)(e.p,{children:"This page was generated automatically from the Perl source file."}),"\n",(0,a.jsx)(e.h2,{id:"perl-modules",children:"Perl Modules"}),"\n",(0,a.jsx)(e.p,{children:"The script uses the following modules:"}),"\n",(0,a.jsxs)(e.ul,{children:["\n",(0,a.jsx)(e.li,{children:(0,a.jsx)(e.code,{children:"DBI"})}),"\n",(0,a.jsx)(e.li,{children:(0,a.jsx)(e.code,{children:"Getopt::Std"})}),"\n"]}),"\n",(0,a.jsx)(e.h2,{id:"database",children:"Database"}),"\n",(0,a.jsxs)(e.ul,{children:["\n",(0,a.jsxs)(e.li,{children:[(0,a.jsx)(e.strong,{children:"Database interface:"})," MySQL via Perl DBI"]}),"\n"]}),"\n",(0,a.jsx)(e.h2,{id:"command-line-options",children:"Command-Line Options"}),"\n",(0,a.jsxs)(e.table,{children:[(0,a.jsx)(e.thead,{children:(0,a.jsxs)(e.tr,{children:[(0,a.jsx)(e.th,{children:"Option"}),(0,a.jsx)(e.th,{children:"Argument"})]})}),(0,a.jsxs)(e.tbody,{children:[(0,a.jsxs)(e.tr,{children:[(0,a.jsx)(e.td,{children:(0,a.jsx)(e.code,{children:"-w"})}),(0,a.jsx)(e.td,{children:"No"})]}),(0,a.jsxs)(e.tr,{children:[(0,a.jsx)(e.td,{children:(0,a.jsx)(e.code,{children:"-h"})}),(0,a.jsx)(e.td,{children:"No"})]}),(0,a.jsxs)(e.tr,{children:[(0,a.jsx)(e.td,{children:(0,a.jsx)(e.code,{children:"-u"})}),(0,a.jsx)(e.td,{children:"Required"})]}),(0,a.jsxs)(e.tr,{children:[(0,a.jsx)(e.td,{children:(0,a.jsx)(e.code,{children:"-p"})}),(0,a.jsx)(e.td,{children:"Required"})]})]})]}),"\n",(0,a.jsx)(e.h3,{id:"example",children:"Example"}),"\n",(0,a.jsx)(e.pre,{children:(0,a.jsx)(e.code,{className:"language-bash",children:"perl create_www_professores.pl -h\n"})}),"\n",(0,a.jsx)(e.h2,{id:"source-code",children:"Source Code"}),"\n",(0,a.jsx)(e.pre,{children:(0,a.jsx)(e.code,{className:"language-perl",children:'#!/usr/bin/perl\r\nuse strict;\r\nuse warnings;\r\nuse DBI;\r\nuse Getopt::Std;\r\n\r\n# -----------------------------------------------------------------------------\r\n# Apresenta listagem de professores.\r\n# -----------------------------------------------------------------------------\r\n$|++;\r\nmy $crlf = "\\n";\r\nmy $aplicativo = $0;\r\n\r\n\r\n# defini\xe7\xe3o para acesso do banco (valores default)\r\nmy $host     = "localhost";\r\nmy $database = "DAELT";\r\nmy $usuario  = "";\r\nmy $senha    = "";\r\n\r\n\r\n# Recupera\xe7\xe3o dos par\xe2metros de entrada (via shell)\r\nmy %opcoes=();\r\ngetopts("whu:p:", \\%opcoes);\r\n\r\n$crlf    = "\\r\\n"     if defined $opcoes{w};\r\n$usuario = $opcoes{u} if defined $opcoes{u};\r\n$senha   = $opcoes{p} if defined $opcoes{p};\r\n\r\nif (defined $opcoes{h})\r\n{\r\n	print STDERR "$aplicativo [-w] [-u <usuario>] [-p <senha>]$crlf";\r\n	exit 0;\r\n}\r\n\r\n\r\n# apresenta\xe7\xe3o do programa\r\nprint STDERR "$aplicativo\\::Apresenta listagem de professores.$crlf";\r\n\r\n\r\n# conex\xe3o com banco de dados\r\nmy ($dbHandle,\r\n    $dbStatement1, $dbStatement2, $dbStatement3,\r\n    $dbStatement4, $dbStatement5, $dbStatement6);\r\nmy @dbLinha;\r\n\r\n$dbHandle = DBI->connect("DBI:mysql:database=$database;host=$host",\r\n                         $usuario, $senha,\r\n                         {PrintError => 0, AutoCommit => 0})\r\n	or die "$aplicativo\\::Falha de conex\xe3o ao banco de dados: $DBI::errstr";\r\n\r\n$dbStatement1 = $dbHandle->prepare(\r\n	"SELECT ID, NOME, EMAIL, EMAIL2 " .\r\n	"FROM DAELT.PROFESSORES " .\r\n	"WHERE ID !=\'0\' AND DATA_FIM IS NULL AND EFETIVO != FALSE " .\r\n	"ORDER BY NOME;");\r\n$dbStatement2 = $dbHandle->prepare(\r\n	"SELECT C.NOME " .\r\n	"FROM DAELT.PROFESSORES A, DAELT.PROFESSORES_GRUPOS B, DAELT.GRUPOS C " .\r\n	"WHERE A.ID = ? AND A.ID = B.ID_PROFESSOR AND B.ID_GRUPO = C.ID AND " .\r\n	      "B.DATA_FIM IS NULL " .\r\n	"ORDER BY C.NOME;");\r\n$dbStatement3 = $dbHandle->prepare(\r\n	"SELECT B.INTERESSE " .\r\n	"FROM DAELT.PROFESSORES A, DAELT.PROFESSORES_INTERESSES B " .\r\n	"WHERE A.ID = ? AND A.ID = B.ID_PROFESSOR " .\r\n	"ORDER BY B.INTERESSE;");\r\n$dbStatement4 = $dbHandle->prepare(\r\n	"SELECT B.TEMA " .\r\n	"FROM DAELT.PROFESSORES A, DAELT.PROFESSORES_TEMAS B " .\r\n	"WHERE A.ID = ? AND A.ID = B.ID_PROFESSOR " .\r\n	"ORDER BY B.TEMA;");\r\n$dbStatement5 = $dbHandle->prepare(\r\n	"SELECT A.NOME, B.ID, B.NOME " .\r\n	"FROM DAELT.GRUPOS A, DAELT.PROFESSORES B " .\r\n	"WHERE A.ID_LIDER = B.ID AND A.ID_LIDER != \'0\';");\r\n$dbStatement6 = $dbHandle->prepare(\r\n	"SELECT ID, NOME, EMAIL, EMAIL2 " .\r\n	"FROM DAELT.PROFESSORES " .\r\n	"WHERE ID !=\'0\' AND DATA_FIM IS NULL AND EFETIVO != TRUE " .\r\n	"ORDER BY NOME;");\r\n\r\n\r\n\r\n# impress\xe3o do pre\xe2mbulo (conforme p\xe1gina)\r\nprint <<PREAMBULO_PAGINA;\r\n<!DOCTYPE html>\r\n<html lang="pt-BR" xmlns="http://www.w3.org/1999/xhtml">\r\n<head>\r\n<meta http-equiv="Content-Type" content="text/html;charset=UTF-8" />\r\n\r\n<title>TCC/DAELT/UTFPr - Engenharia</title>\r\n\r\n<base href="https://nupet.daelt.ct.utfpr.edu.br/tcc/" />\r\n\x3c!-- <base href="file:///media/DADOS/utfpr/tcc/www/" /> --\x3e\r\n\r\n<link rel="stylesheet" type="text/css" href="css/meus-estilos.css" />\r\n\r\n</head>\r\n\r\n<body>\r\n\r\n\x3c!-- ####### Novo bloco de informa\xe7\xf5es: Apresenta\xe7\xe3o do professor ######## --\x3e \r\n<div>\r\n<table id="tabelas-apresentacao">\r\n<tr>\r\n	<td>\r\n		<img style="width:250px" src="imagens/logo_UTFPR.jpg" alt="UTFPR" />\r\n	</td>\r\n\r\n	<td>\r\n		<b>Trabalho de Conclus\xe3o de Curso - Engenharia</b>\r\n	    	<p><a href="http://www.daelt.ct.utfpr.edu.br">Departamento Acad\xeamico de Eletrot\xe9cnica</a></p>\r\n		<p><a href="http://www.utfpr.edu.br">Universidade Tecnol\xf3gica Federal do Paran\xe1</a></p>\r\n		<p>Av. Sete de Setembro, 3165, Rebou\xe7as, 80230-910, Curitiba, Paran\xe1, Brasil</p>\r\n	</td>\r\n</tr>\r\n</table>\r\n</div>\r\n\r\n\r\n\x3c!-- ############# Nova bloco de informa\xe7\xf5es: Menu de op\xe7\xf5es ############# --\x3e \r\n<div>\r\n<ul class="listas-menu">\r\n	<li><a href="engenharia/index.html">Engenharia</a></li>\r\n	<li><a href="tecnologia/index.html">Tecnologia</a></li>\r\n</ul>\r\n<br style="clear:both" />\r\n</div>\r\n\r\n\r\nPREAMBULO_PAGINA\r\n\r\n# imprime lista dos grupos\r\n$dbStatement5->execute();\r\n\r\nprint <<PREAMBULO_LISTA_LIDERES;\r\n\x3c!-- ########## Nova bloco de informa\xe7\xf5es: Lista de professores ########## --\x3e \r\n<div>\r\n<h1><a id="lista_grupos">Lista de grupos do DAELT</a></h1>\r\n\r\n<p>Abaixo segue a lista de grupos, e seus respectivos l\xedderes. Estes professores receber\xe3o as propostas de Metodologia Aplicada ao TCC e as distribuir\xe3o entre os membros de seus grupos para avalia\xe7\xe3o.</p>\r\n<table class="tabelas-professor">\r\n\r\n<tr>\r\n	<th>Grupo</th>\r\n	<th>L\xedder [C\xf3digo]</th>\r\n</tr>\r\n\r\nPREAMBULO_LISTA_LIDERES\r\n\r\nwhile ( @dbLinha = $dbStatement5->fetchrow_array )\r\n{\r\n	# imprime grupos + l\xedder\r\n	print "<tr>$crlf";\r\n	print "\\t<td>$dbLinha[0]</td>";\r\n	print "\\t<td>$dbLinha[2] [$dbLinha[1]]</td>";\r\n	print "</tr>$crlf";\r\n}\r\n\r\nprint <<PERORACAO_LISTA_LIDERES;\r\n</table>\r\n\r\n</div>\r\n\r\n\r\nPERORACAO_LISTA_LIDERES\r\n\r\n\r\n# imprime lista dos professores\r\n$dbStatement1->execute();\r\n\r\nprint <<PREAMBULO_LISTA_PROFESSORES;\r\n\x3c!-- ########## Nova bloco de informa\xe7\xf5es: Lista de professores ########## --\x3e \r\n<div>\r\n<h1><a id="lista_professores">Lista de professores do DAELT</a></h1>\r\n\r\n<p>Abaixo segue a lista de professores, suas \xe1reas de atua\xe7\xe3o, o grupo a que pertence e sugest\xf5es de trabalhos que eles podem orientar. Recomenda-se que o aluno/grupo procure professores cujo \xe1rea de interesse seja similar \xe0quela na qual deseja desenvolver o TCC.</p>\r\n<table class="tabelas-professor">\r\n	<col width="25%" />\r\n	<col width="20%" />\r\n	<col width="20%" />\r\n	<col width="35%" />\r\n\r\n<tr>\r\n	<th>Professor [C\xf3digo]</th>\r\n	<th>Grupo</th>\r\n	<th>\xc1rea de interesse</th>\r\n	<th>Tema para TCC</th>\r\n</tr>\r\n\r\nPREAMBULO_LISTA_PROFESSORES\r\n\r\nwhile ( @dbLinha = $dbStatement1->fetchrow_array )\r\n{\r\n	my $professor_id_saved = $dbLinha[0];\r\n\r\n	# imprime nome + emails\r\n	print "<tr>$crlf";\r\n	print "\\t<td>$dbLinha[1] [$dbLinha[0]]";\r\n	print "<br /><span class = \\"visual-emails\\">" .\r\n	    embaralha_email($dbLinha[2]) . "</span>" if (defined $dbLinha[2]);\r\n	print "<br /><span class = \\"visual-emails\\">" .\r\n	    embaralha_email($dbLinha[3]) . "</span>" if (defined $dbLinha[3]);\r\n	print "</td>$crlf";\r\n\r\n	# imprime grupos\r\n	$dbStatement2->bind_param(1, $professor_id_saved);\r\n	$dbStatement2->execute();\r\n\r\n	print "\\t<td>";\r\n	my $checa_existencia = 0;\r\n	while ( @dbLinha = $dbStatement2->fetchrow_array )\r\n	{\r\n		print "<ul>$crlf" if $checa_existencia == 0;\r\n		$checa_existencia = 1;\r\n\r\n		print "\\t\\t<li>$dbLinha[0]</li>$crlf";\r\n	}\r\n	print "\\t</ul>" if $checa_existencia == 1;\r\n	print "</td>$crlf";\r\n\r\n	# imprime interesses\r\n	$dbStatement3->bind_param(1, $professor_id_saved);\r\n	$dbStatement3->execute();\r\n\r\n	print "\\t<td>";\r\n	$checa_existencia = 0;\r\n	while ( @dbLinha = $dbStatement3->fetchrow_array )\r\n	{\r\n		print "<ul>$crlf" if $checa_existencia == 0;\r\n		$checa_existencia = 1;\r\n\r\n		print "\\t\\t<li>$dbLinha[0]</li>$crlf";\r\n	}\r\n	print "\\t</ul>" if $checa_existencia == 1;\r\n	print "</td>$crlf";\r\n\r\n	# imprime temas\r\n	$dbStatement4->bind_param(1, $professor_id_saved);\r\n	$dbStatement4->execute();\r\n\r\n	print "\\t<td>";\r\n	$checa_existencia = 0;\r\n	while ( @dbLinha = $dbStatement4->fetchrow_array )\r\n	{\r\n		print "<ul>$crlf" if $checa_existencia == 0;\r\n		$checa_existencia = 1;\r\n\r\n		print "\\t\\t<li>$dbLinha[0]</li>$crlf";\r\n	}\r\n	print "\\t</ul>" if $checa_existencia == 1;\r\n	print "</td>$crlf</tr>$crlf";\r\n}\r\n\r\nprint <<PERORACAO_LISTA_PROFESSORES;\r\n</table>\r\n\r\n</div>\r\n\r\n\r\nPERORACAO_LISTA_PROFESSORES\r\n\r\n\r\n# imprime lista dos professores\r\n$dbStatement6->execute();\r\n\r\nprint <<PREAMBULO_LISTA_VISITANTES;\r\n\x3c!-- ########## Nova bloco de informa\xe7\xf5es: Lista de visitantes ########## --\x3e \r\n<div>\r\n<h1><a id="lista_visitantes">Lista de visitantes/colaboradores do DAELT</a></h1>\r\n\r\n<p>Abaixo segue a lista de visitantes/colaboradores, suas \xe1reas de atua\xe7\xe3o, e o grupo do DAELT com o qual j\xe1 colaboraram.</p>\r\n<table class="tabelas-professor">\r\n	<col width="50%" />\r\n	<col width="50%" />\r\n\r\n<tr>\r\n	<th>Visitante [C\xf3digo]</th>\r\n	<th>Grupo</th>\r\n</tr>\r\n\r\nPREAMBULO_LISTA_VISITANTES\r\n\r\nwhile ( @dbLinha = $dbStatement6->fetchrow_array )\r\n{\r\n	my $professor_id_saved = $dbLinha[0];\r\n\r\n	# imprime nome + emails\r\n	print "<tr>$crlf";\r\n	print "\\t<td>$dbLinha[1] [$dbLinha[0]]";\r\n	print "<br /><span class = \\"visual-emails\\">" .\r\n	    embaralha_email($dbLinha[2]) . "</span>" if (defined $dbLinha[2]);\r\n	print "<br /><span class = \\"visual-emails\\">" .\r\n	    embaralha_email($dbLinha[3]) . "</span>" if (defined $dbLinha[3]);\r\n	print "</td>$crlf";\r\n\r\n	# imprime grupos\r\n	$dbStatement2->bind_param(1, $professor_id_saved);\r\n	$dbStatement2->execute();\r\n\r\n	print "\\t<td>";\r\n	my $checa_existencia = 0;\r\n	while ( @dbLinha = $dbStatement2->fetchrow_array )\r\n	{\r\n		print "<ul>$crlf" if $checa_existencia == 0;\r\n		$checa_existencia = 1;\r\n\r\n		print "\\t\\t<li>$dbLinha[0]</li>$crlf";\r\n	}\r\n	print "\\t</ul>" if $checa_existencia == 1;\r\n	print "</td>$crlf</tr>$crlf";\r\n}\r\n\r\nprint <<PERORACAO_LISTA_VISITANTES;\r\n</table>\r\n\r\n</div>\r\n\r\n\r\nPERORACAO_LISTA_VISITANTES\r\n\r\n\r\n# impress\xe3o da peroracao (conforme p\xe1gina)\r\nprint <<PERORACAO;\r\n\x3c!-- ############# Nova bloco de informa\xe7\xf5es: Valida\xe7\xf5es HTML ############ --\x3e \r\n<div>\r\n<p style="text-align:center">\r\n <a href="https://validator.w3.org/check?uri=referer">\r\n    <img src="https://www.w3.org/Icons/valid-xhtml10" alt="Valid XHTML 1.0 Transitional" height="31" width="88" />\r\n </a>\r\n\r\n <a href="https://jigsaw.w3.org/css-validator/check/referer">\r\n    <img style="border:0;width:88px;height:31px" src="https://jigsaw.w3.org/css-validator/images/vcss" alt="CSS v\xe1lido!" />\r\n </a>\r\n</p>\r\n</div>\r\n\r\n\r\n</body>\r\n</html>\r\nPERORACAO\r\n\r\n# desconex\xe3o com banco de dados\r\n$dbHandle->disconnect();\r\nexit 0;\r\n\r\n\r\n# -----------------------------------------------------------------------------\r\n# Embaralha email para evitar spam!\r\n# -----------------------------------------------------------------------------\r\nsub embaralha_email\r\n{\r\n	my $email = $_[0];\r\n\r\n	if ($email =~ /^([\\w\\.\\-\\_]+)\\@([\\w\\.\\-\\_]+[a-zA-Z]{2,})$/)\r\n	{\r\n		my $nome = $1;\r\n		my $host = $2;\r\n		$host =~ s/\\./ [dot] /g;\r\n		$email = $nome . " [at] " . $host;\r\n	}\r\n\r\n	return $email;\r\n}\n'})})]})}function p(r={}){let{wrapper:e}={...(0,s.R)(),...r.components};return e?(0,a.jsx)(e,{...r,children:(0,a.jsx)(c,{...r})}):c(r)}},28453(r,e,n){n.d(e,{R:()=>i,x:()=>o});var t=n(96540);let a={},s=t.createContext(a);function i(r){let e=t.useContext(s);return t.useMemo(function(){return"function"==typeof r?r(e):{...e,...r}},[e,r])}function o(r){let e;return e=r.disableParentContext?"function"==typeof r.components?r.components(a):r.components||a:i(r.components),t.createElement(s.Provider,{value:e},r.children)}}}]);